import { getVersionWithDate } from "./getVersion";
import { buildExtensionTelemetryProperties } from "./extensionTelemetry";
import posthog from "posthog-js";
import type { CaptureResult } from "posthog-js";

let initialized = false;

const getLocalStorage = (): Storage | undefined => {
  try {
    return window.localStorage;
  } catch {
    return undefined;
  }
};

export const initPostHog = (): void => {
  if (initialized) return;
  if (window.roamAlphaAPI.graph.isEncrypted) return;
  if (window.roamAlphaAPI.graph.type === "offline") return;
  const propertyDenylist = new Set([
    "$ip",
    "$device_id",
    "$geoip_city_name",
    "$geoip_latitude",
    "$geoip_longitude",
    "$geoip_postal_code",
    "$geoip_subdivision_1_name",
    "$raw_user_agent",
    "$referrer",
    "$referring_domain",
  ]);
  posthog.init("REDACTED", {
    autocapture: false,
    disable_session_recording: true,
    api_host: "https://us.i.posthog.com",
    person_profiles: "identified_only",
    capture_pageview: false,
    property_denylist: [...propertyDenylist],
    before_send: (result: CaptureResult | null) => {
      if (result !== null) {
        result.properties = Object.fromEntries(
          Object.entries(result.properties).filter(
            ([k]) => !propertyDenylist.has(k),
          ),
        );
      }
      return result;
    },
    loaded: (posthog) => {
      const extensionTelemetry = buildExtensionTelemetryProperties({
        versionMetadata: getVersionWithDate(),
        storage: getLocalStorage(),
      });
      const userUid = window.roamAlphaAPI.user.uid() || "";
      const graphName = window.roamAlphaAPI.graph.name;
      const sessionTelemetry = {
        ...extensionTelemetry,
        graphName,
      };
      if (userUid) posthog.identify(userUid);
      posthog.register_for_session(sessionTelemetry);
      posthog.capture("Extension Loaded", sessionTelemetry);
      initialized = true;
    },
  });
  /* eslint-enable @typescript-eslint/naming-convention  */
};

export const enablePostHog = (): void => {
  initPostHog();
  posthog.opt_in_capturing();
};

export const disablePostHog = (): void => {
  if (initialized) posthog.opt_out_capturing();
};
"use client";

import posthog from "posthog-js";
import { PostHogProvider as PHProvider } from "posthog-js/react";
import { Toaster } from "@repo/ui/components/ui/sonner";
import { useEffect } from "react";
import PostHogPageView from "./PostHogPageView";

if (
  !process.env.NEXT_PUBLIC_POSTHOG_KEY ||
  !process.env.NEXT_PUBLIC_POSTHOG_HOST
) {
  throw new Error("PostHog environment variables are not set");
}

export const PostHogProvider = ({
  children,
}: {
  children: React.ReactNode;
}) => {
  useEffect(() => {
    posthog.init(process.env.NEXT_PUBLIC_POSTHOG_KEY!, {
      api_host: process.env.NEXT_PUBLIC_POSTHOG_HOST!,
      capture_pageview: false,
    });
  }, []);

  return (
    <PHProvider client={posthog}>
      <PostHogPageView />
      {children}
      <Toaster />
    </PHProvider>
  );
};
